LIBC_INLINE LIBC_CONSTEXPR double round(double x) {
#if defined(__LIBC_USE_BUILTIN_ROUND) && !defined(LIBC_USE_CONSTEXPR)
  return __builtin_round(x);
#else
  return fputil::round(x);
#endif
}

